def append_scores(scores):
    f = open('scores.txt', 'a')
    try:
        for s in scores:
            f.write(str(s) + '\n')
    finally:
        f.close()

def save_data(data):
    try:
        f = open('data.txt', 'a')
        f.write(data)
    except IOError as e:
        print('Error:', e)
    finally:
        f.close()

def append_to_file(filepath, lines):
    with open(filepath, 'a') as f:
        for line in lines:
            f.write(line + '\n')

