import os

def append_diary(filepath):
    if not os.path.exists(os.path.dirname(filepath)):
        print(f'Directory does not exist: {os.path.dirname(filepath)}')
        return
    try:
        with open(filepath, 'a') as file:
            while True:
                text = input('Enter diary entry (quit to stop): ')
                if text == 'quit':
                    break
                file.write(text + '\n')
    except PermissionError:
        print(f'Permission denied: cannot write to {filepath}')
    except Exception as e:
        print(f'Unexpected error: {e}')

append_diary('diary.txt')
